var a=`1060-beef-rendang-malaysian-style`;var i=`world-1060`;var t=`MY`;var s=`southeast-asia`;var l=4;var r=288;var g={en:`Beef Rendang Malaysian Style`,ua:`Ренданг із яловичини по-малайзійськи`};var o={en:`Beef Rendang Malaysian Style is a dish from Malaysia prepared with shallot, garlic, galangal, lemongrass. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Ренданг із яловичини по-малайзійськи, страва кухні країни Малайзія, яку готують із таких продуктів: цибуля шалот, часник, галангал, лемонграс. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`shallot`,170,`g`],[`garlic`,6,`clove`],[`galangal`,40,`g`],[`lemongrass`,3,`pcs`],[`ground-turmeric`,6,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 145 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 145 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:145,i:[[`beef-chuck`,1050,`g`],[`coconut-milk`,1e3,`ml`],[`makrut-lime-leaves`,5,`leaf`],[`ground-coriander`,7,`g`]]},{en:`Simmer the liquid and flavorings uncovered for about 130 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 130 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:130,i:[[`palm-sugar`,35,`g`],[`tamarind-concentrate`,28,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`toasted-coconut-flakes`,65,`g`]]}];var u={slug:a,id:i,country:`MY`,region:s,servings:4,minutes:288,title:g,text:o,steps:d};export{t as country,u as default,i as id,r as minutes,s as region,l as servings,a as slug,d as steps,o as text,g as title};